    # d1[rider] = bike on day 1, d2[rider] = bike on day 2
    for r in range(4):
        if d1[r] == d2[r]:
            return False
    if d1[R] == F or d2[R] == F:
        return False
    if d1[Y] == J or d2[Y] == J:
        return False
    if H not in (d1[T], d2[T]):
        return False
    # Yuki's day-1 bike is tested by Seamus on day 2
    if d2[S] != d1[Y]:
        return False
    return True

scenarios = []
for d1 in permutations(range(4)):
    if d1[T] != J:
        continue
    for d2 in permutations(range(4)):
        if valid(d1, d2):
            scenarios.append((d1, d2))

