    n = len(poly)
    for e in edges:
        a, b = tuple(e)
        m = ((a[0]+b[0])/2, (a[1]+b[1])/2)
        if min(dist_seg(m, poly[i], poly[(i+1) % n]) for i in range(n)) < 1e-2: continue
