    n = len(c)
    vec = [sub(c[(i+1) % n], c[i]) for i in range(n)]
    ln = [math.hypot(*v) for v in vec]
    crs = [cross(vec[i], vec[(i+1) % n]) for i in range(n)]
    convex = all(x > 0 for x in crs) or all(x < 0 for x in crs)
    ang = [dot(vec[i], vec[(i+1) % n])/(ln[i]*ln[(i+1) % n]) for i in range(n)]
    def par(i, j): return abs(cross(vec[i], vec[j]))/(ln[i]*ln[j]) < 3e-3
    if n == 3:
        right = any(abs(a) < 3e-3 for a in ang)
        return 4 if right else 3
    if n == 4:
        if not convex: return None
        p13 = par(0, 2); p24 = par(1, 3)
        if p13 and p24:
            rect = all(abs(a) < 3e-3 for a in ang)
            if rect:
                return 2 if rel(ln[0], ln[1]) else 1
