riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    for r in riders:
        if d1[r] == d2[r]:
            return False
        if r == "R" and "F" in (d1[r], d2[r]):
            return False
        if r == "Y" and "J" in (d1[r], d2[r]):
            return False
    if "H" not in (d1["T"], d2["T"]):
