adj = {i: set() for i in range(len(nodes))}
for e in edges:
    a, b = tuple(e)
    adj[idx[a]].add(idx[b]); adj[idx[b]].add(idx[a])

# enumerate simple cycles
cycles = {}
t0 = time.time()
def dfs(start, cur, visited, pathl):
    if time.time() - t0 > 3.5:
        return
    for nb in adj[cur]:
        if nb == start and len(pathl) >= 3:
            key = frozenset(frozenset((pathl[i], pathl[(i + 1) % len(pathl)])) for i in range(len(pathl)))
            if key not in cycles:
                cycles[key] = list(pathl)
        elif nb > start and nb not in visited:
            visited.add(nb); pathl.append(nb)
            dfs(start, nb, visited, pathl)
            pathl.pop(); visited.discard(nb)
for s in range(len(nodes)):
    dfs(s, s, {s}, [s])

def cross(u, v): return u[0]*v[1]-u[1]*v[0]
def dot(u, v): return u[0]*v[0]+u[1]*v[1]
def norm(u): return math.hypot(*u)

def seg_inter(p1, p2, p3, p4):
    d1 = cross((p2[0]-p1[0], p2[1]-p1[1]), (p3[0]-p1[0], p3[1]-p1[1]))
    d2 = cross((p2[0]-p1[0], p2[1]-p1[1]), (p4[0]-p1[0], p4[1]-p1[1]))
    d3 = cross((p4[0]-p3[0], p4[1]-p3[1]), (p1[0]-p3[0], p1[1]-p3[1]))
    d4 = cross((p4[0]-p3[0], p4[1]-p3[1]), (p2[0]-p3[0], p2[1]-p3[1]))
    return d1*d2 < -1e-9 and d3*d4 < -1e-9

def inside(pt, poly):
    x, y = pt; c = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]; x2, y2 = poly[(i+1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y-y1)*(x2-x1)/(y2-y1)
            if xi > x:
                c = not c
    return c

TOL = 1e-3
found = {}
for key, cyc in cycles.items():
    P = [nodes[i] for i in cyc]
    n = len(P)
    # reduce collinear vertices
    keep = []
    for i in range(n):
        a, b, c = P[i-1], P[i], P[(i+1) % n]
        u = (b[0]-a[0], b[1]-a[1]); v = (c[0]-b[0], c[1]-b[1])
        s = abs(cross(u, v)) / (norm(u)*norm(v))
        if s > TOL:
            keep.append(b)
    k = len(keep)
    if k < 3:
        continue
    # simple check
    ok = True
    for i in range(k):
        for j in range(i+2, k):
            if i == 0 and j == k-1: continue
            if seg_inter(keep[i], keep[(i+1) % k], keep[j], keep[(j+1) % k]):
                ok = False
    if not ok:
        continue
    # no diagonals / interior nodes
    cset = set(cyc)
    bad = False
    for i in cset:
        for j in adj[i]:
            if j in cset and frozenset((i, j)) not in key:
                bad = True
    for i, p in enumerate(nodes):
        if i not in cset and inside(p, keep):
            bad = True
    if bad:
        continue
    V = [(keep[(i+1) % k][0]-keep[i][0], keep[(i+1) % k][1]-keep[i][1]) for i in range(k)]
    L = [norm(v) for v in V]
    def par(a, b): return abs(cross(V[a], V[b]))/(L[a]*L[b]) < TOL
    def perp(a, b): return abs(dot(V[a], V[b]))/(L[a]*L[b]) < TOL
    shape = None
    if k == 3:
        right = any(perp(i, (i+1) % 3) for i in range(3))
        shape = 4 if right else 3
    elif k == 4:
        pp = par(0, 2) + par(1, 3)
        if pp == 2:
            if perp(0, 1):
                sq = abs(L[0]-L[1])/L[0] < TOL
                shape = 2 if sq else 1
            else:
                shape = 5
        elif pp == 1:
            shape = 6
    elif k == 5 or k == 6:
        crs = [cross(V[i], V[(i+1) % k]) for i in range(k)]
        convex = all(c > 0 for c in crs) or all(c < 0 for c in crs)
        eq = max(L)-min(L) < TOL*max(L)
        angs = [math.atan2(abs(crs[i]), dot(V[i], V[(i+1) % k])) for i in range(k)]
        eqa = max(angs)-min(angs) < TOL
        regular = convex and eq and eqa
        if k == 5:
            shape = 9 if regular else (7 if convex else 8)
        else:
            shape = 10 if regular else None
    if shape is not None:
        found.setdefault(shape, []).append(keep)

found_set = sorted(found)
print("nodes", len(nodes), "edges", len(edges), "cycles", len(cycles))
for s in found_set:
    print("shape", s, "count", len(found[s]))
expected = {1, 5, 7, 8}
print("found:", found_set, "claimed E:", sorted(expected))
print("CHECK PASS" if set(found_set) == expected else "CHECK FAIL")
