import json

def factorize(n):
    factors = {}
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

n = 33146799
f = factorize(n)

prod = 1
for p, e in f.items():
    prod *= p ** e

assert prod == n

primes = sorted(f)
final = ", ".join(str(p) for p in primes)

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "n": n,
        "factorization": {str(p): e for p, e in sorted(f.items())},
        "product_check": prod == n,
        "method": "trial division"
    }
}))
